class StockPortfolioTracker:
    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def add_stock(self, stock):
        self.portfolio.append(stock)

    def remove_stock(self, stock):
        if stock in self.portfolio:
            self.portfolio.remove(stock)
            return True
        return False

    def buy_stock(self, stock, quantity):
        stock_price = stock['price']
        stock_quantity = stock['quantity']
        if stock_quantity >= quantity and self.cash_balance >= stock_price * quantity:
            self.cash_balance -= stock_price * quantity
            stock['quantity'] -= quantity
            if stock['quantity'] == 0:
                self.remove_stock(stock)
            return True
        return False

    def sell_stock(self, stock, quantity):
        stock_price = stock['price']
        stock_quantity = stock['quantity']
        if stock_quantity >= quantity:
            self.cash_balance += stock_price * quantity
            stock['quantity'] -= quantity
            if stock['quantity'] == 0:
                self.remove_stock(stock)
            return True
        return False

    def calculate_portfolio_value(self):
        total_value = 0
        for stock in self.portfolio:
            total_value += stock['price'] * stock['quantity']
        return total_value

    def get_portfolio_summary(self):
        total_value = self.calculate_portfolio_value()
        summary = [{'name': stock['name'], 'value': stock['price'] * stock['quantity']} for stock in self.portfolio]
        return total_value, summary

    def get_stock_value(self, stock):
        return stock['price'] * stock['quantity']
